/* --- cinemática del estudio: interruptor y repetición ---
   La intro ocurre ANTES de que exista ninguna partida, así que su ajuste NO
   puede vivir en G.ajustes (en el arranque G es null y sería ilegible justo
   cuando hace falta). Se guarda aparte, en el navegador, igual que la portada
   elegida y por el mismo motivo. */
function introOn(){try{return localStorage.getItem('dinIntro')!=='0';}catch(e){return true;}}
function setIntroOn(v){
  try{localStorage.setItem('dinIntro',v?'1':'0');}catch(e){}
  intentar('sfx',()=>sfx('ok'));
  /* Mismo reparto que setPortada(): esta tarjeta sale en tres pantallas y hay
     que repintar la que está delante, no otra, o parece que el botón te echa. */
  if(window.__enModoSel)renderModoSel();else if(G)render();else renderPortada();
}
/* Lector real del fallo: si el mp4 no está al lado, quien pulsó el botón merece
   saber POR QUÉ no pasa nada y dónde debería estar el archivo. En el arranque
   normal ese mismo fallo es mudo, que nadie quiere un error al abrir el juego. */
function verIntroAhora(){
  dinastiaIntro(true,function(){
    toast('🎬 No encuentro el vídeo del estudio. Tiene que estar en marca/nexus-digital-intro.mp4, junto al juego.');
  });
}
function selectorPortadaHTML(){
  const k=portadaSel(),ion=introOn();
  return `<div class="card"><small>🖼️ PORTADA DEL JUEGO</small>
    <p class="mut" style="margin-bottom:6px">Nueve carátulas distintas. Se guarda en este navegador y se aplica a la pantalla de inicio.</p>
    <div class="btnrow wrap">${PORTADAS.map(p=>`<button class="mini ${k===p[0]?'':'sec'}" onclick="setPortada('${p[0]}')">${p[1]}</button>`).join('')}</div>
    <p class="mut">${esc((PORTADAS.find(p=>p[0]===k)||PORTADAS[0])[2])}</p>
  </div>
  <div class="card"><small>🎬 CINEMÁTICA DEL ESTUDIO</small>
    <p class="mut" style="margin-bottom:6px">Los diez segundos de Nexus Digital al abrir el juego. Sale una vez por sesión y se salta con un toque.</p>
    <div class="btnrow wrap">
      <button class="mini ${ion?'':'sec'}" onclick="setIntroOn(${!ion})">${ion?'ACTIVADA':'DESACTIVADA'}</button>
      <button class="mini sec" onclick="verIntroAhora()">▶ Verla ahora</button>
    </div>
    <p class="mut">${ion?'Se salta tocando la pantalla. Si el vídeo falla o no está, el juego arranca igual y no dice nada.':'Apagada: el juego abre directo en el menú.'}</p>
  </div>`;
}

