if (-not $SinIntro) {
    $mp4 = "$proy\marca\nexus-digital-intro.mp4"
    if (Test-Path $mp4) {
        Copy-Item $mp4 "$assets\intro.mp4"
        # La intro se inyecta en la COPIA que va al APK, nunca en el HTML base:
        # el juego de escritorio se queda limpio.
        $intro = Get-Content "$raiz\intro.html" -Raw -Encoding UTF8
        # String.Replace literal, NO -replace: el HTML del juego esta lleno de $ y \ que una
        # sustitucion por regex interpretaria como grupos y escapes, corrompiendo el archivo.
        # '<body>' aparece exactamente una vez, asi que basta con esto.
        if ($html -notmatch '<body>') { throw "no se encontro <body> en el HTML del juego" }
        $html  = $html.Replace('<body>', "<body>`r`n" + $intro)
        Write-Host "      intro de marca inyectada (intro.mp4, 2 MB)"
    } else {
        Write-Host "      AVISO: no se encontro la cinematica, se compila sin intro" -ForegroundColor Yellow
    }
}
